    const desTextW = getTextWidth(desText, desFontSize, "bold", fontStack);
    const desPadY = toFiniteNumber(cfg.designationPaddingY, 2.0) * baseScale;
    const desW = Math.min(maxDesW, Math.max(width * 0.38, desTextW + desPadX * 2));
    const desH = desFontSize * 1.02 + desPadY * 2;
    const desOffX = toFiniteNumber(cfg.designationOffsetX, 0) * baseScale;
    const desOffY = toFiniteNumber(cfg.designationOffsetY, 0) * baseScale;
    const baseDesY = baseNomBottom + desPadTop;
    const baseDesBottom = baseDesY + desH;
    const desX = (width - desW) / 2 + desOffX;
    const desY = baseDesY + desOffY;
    const desShape = cfg.designationShape || "pill";

